import json, numpy as np
from sklearn.linear_model import Ridge, HuberRegressor, QuantileRegressor
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline
D=np.load('data.npz');X=D['X'];Y=D['Y'];G=D['G'];S=D['S'];names=list(D['names']);ns=['time','time2'];x=X[:,[names.index(n) for n in ns]]
res=[]
for group in ['all','post','weighted','late']:
 for curve in ['quad','linear','sat20','sat40','quad_hr','quad_skin','quad_hrskin']:
  n={'quad':['time','time2'],'linear':['time'],'sat20':['sat20'],'sat40':['sat40'],'quad_hr':['time','time2','hr_ema15'],'quad_skin':['time','time2','skin_temp_ema15'],'quad_hrskin':['time','time2','hr_ema15','skin_temp_ema15']}[curve]
  x=X[:,[names.index(k) for k in n]]
  for loss in ['mse','huber','mae']:
   p=np.zeros(len(Y))
   for g in np.unique(G):
    tr=G!=g;te=~tr
    if group=='post':tr=tr&S
    if group=='late':tr=tr&(X[:,names.index('origin')]>=.25)
    w=np.ones(sum(tr))
    if group=='weighted':w=np.where(S[tr],1,.2)
    for gg in np.unique(G[tr]):w[G[tr]==gg]/=w[G[tr]==gg].sum()
    w*=sum(tr)/sum(w)
    if loss=='mse':m=Ridge(alpha=.1)
    elif loss=='huber':m=HuberRegressor(epsilon=1.2,alpha=.1,max_iter=300)
    else:m=QuantileRegressor(quantile=.5,alpha=.003,solver='highs')
    sc=StandardScaler().fit(x[tr]);m.fit(sc.transform(x[tr]),Y[tr],sample_weight=w);p[te]=m.predict(sc.transform(x[te]))
   mae=np.mean([abs(p[G==g]-Y[G==g]).mean() for g in np.unique(G)]);post=np.mean([abs(p[(G==g)&S]-Y[(G==g)&S]).mean() for g in np.unique(G[S])])
   res.append((float(.65*mae+.35*post),float(mae),float(post),group,curve,loss))
print(*sorted(res),sep='\n')
json.dump(res,open('curve_results.json','w'))
PY
